'use strict';
const groups = [{"id": "centro", "number": "01", "title": "Centro on foot", "timing": "ANY FREE AFTERNOON", "color": "pink", "description": "The centre is small and flat enough to walk. Two pedestrian streets, the cathedral square, and a church on a hill at each end.", "sections": [["WANDER", [["realguadalupe", "Andador Real de Guadalupe", "the main pedestrian street: cafés, amber shops and textiles"], ["cathedral", "Cathedral & Plaza de la Paz", "the yellow baroque front on the main square"], ["walkingtour", "Free walking tour", "tip-based; a good first afternoon", "The guides can also set up a shared temazcal with other travellers."], ["kinoki", "Kinoki", "independent cinema and café with a roof terrace"], ["cerrillo", "Jardín el Cerrillo", "the small square of the El Cerrillo barrio"]]], ["TWO HILLTOP CHURCHES", [["guadalupechurch", "Iglesia de Guadalupe", "up the steps at the east end of Real de Guadalupe", "Go late in the afternoon for the light over the rooftops."], ["cerrito", "Cerrito de San Cristóbal", "the steeper staircase on the west side, with the wider view"]]]], "note": "The town sits at about 2,200 m. The first days, take the stairs slowly."}, {"id": "markets", "number": "02", "title": "Markets & Santo Domingo", "timing": "A MORNING · MARKETS ARE BEST EARLY", "color": "green", "description": "The working market first, then the craft stalls around the church, all a few blocks north of the main square.", "sections": [["THE MARKET", [["mercado", "Mercado Municipal", "the everyday market: produce, dried chillies, spices, copal resin", "Look for the aisles of candles sold for altars and rituals. Ask before photographing people."]]], ["SANTO DOMINGO", [["santodomingo", "Templo de Santo Domingo", "the carved pink baroque front"], ["caridad", "Mercado de la Caridad y Santo Domingo", "craft stalls around the churches: embroidery, amber, wool"], ["textiles", "Centro de Textiles del Mundo Maya", "Maya weaving, in the old convent beside the church"]]]], "note": "Carry small notes and coins for the stalls."}, {"id": "ceremonies", "number": "03", "title": "Ceremonies", "timing": "TWO UNHURRIED HALF-DAYS", "color": "blue", "description": "A sweat lodge and a cacao ceremony. Neither can be booked online, so both need arranging in the first days.", "sections": [["TEMAZCAL", [["temazcal", "Temazcal ceremony", "about 3 hours, around 90 minutes of it inside the lodge", "500–1,000 pesos each, depending on the size of the group. Local families run group ones: ask the free walking tour guides to set up a shared session once we’re there.", [["Brooke Beyond · temazcal notes", "https://brookebeyond.com/san-cris-travel-guide"]]]]], ["CACAO", [["cacao", "Cacao ceremony with Xmal", "2–3 hours: an altar, singing, dancing and raw cacao", "Xmal is a third-generation Tzotzil shaman and speaks some English. She talks with you first and shapes the ceremony around it. No price listed. Brooke shares her contact by email only.", [["Brooke Beyond · cacao ceremony", "https://brookebeyond.com/san-cris-travel-guide"]]]]]], "note": "Write to Brooke for Xmal’s contact before we arrive: it comes by email and may take a few days. The temazcal can wait until we’re there."}, {"id": "green", "number": "04", "title": "Green half-days", "timing": "AFTER WORK · ONE AT A TIME", "color": "green", "description": "Gardens, a river arch and the cemetery. Each is a short taxi or colectivo from the centre.", "sections": [["GARDENS", [["jade", "Casa Corazón de Jade", "a museum-garden of local and medicinal plants; tea comes with the ticket"], ["moxviquil", "Moxviquil orchid garden", "reserve and orchid garden on the north edge of town"], ["encuentro", "Huerta Parque el Encuentro", "park and kitchen garden to the east"]]], ["FURTHER OUT", [["arcotete", "El Arcotete", "a limestone arch over a river, with short trails"], ["panteon", "Panteón Municipal", "the cemetery, with tombs painted like small houses"]]]], "note": "It rains less from November, but afternoons cool fast. Take a layer."}, {"id": "museums", "number": "05", "title": "Museums", "timing": "FOR A GREY AFTERNOON", "color": "pink", "description": "Three small ones, each an hour or so.", "sections": [["SMALL MUSEUMS", [["nabolom", "Na Bolom", "the house of Frans and Trudi Blom: Lacandon Maya photographs, library and garden"], ["amber", "Museo del Ámbar", "Chiapas amber, in the old La Merced convent"], ["kakaw", "Kakaw Museo del Cacao", "cacao and chocolate, with a tasting"]]]], "note": "Check opening days before walking over: several close on Mondays."}, {"id": "work", "number": "06", "title": "Desk days", "timing": "WEEKDAY MORNINGS", "color": "blue", "description": "Four coworking spaces and six cafés with wifi good enough to work from.", "sections": [["COWORKING", [["centralita", "Centralita", "two sites, Centro and El Cerrillo; pet friendly, lockers, a free trial day", "Their site lists a day pass at 590 pesos, 6 days in a month at 1,200 and 14 days at 1,750. Older blogs say 130 a day, so ask at the door. Centro: weekdays 7:30am–9pm, weekends 9am–5pm.", [["Centralita", "https://www.centralitacowork.com/"]]], ["jovel", "Instituto Jovel", "Francisco I. Madero 45; garden, outdoor tables, coffee and tea included", "150 pesos a day. Monday to Friday, 9am–4pm.", [["Instituto Jovel coworking", "https://www.institutojovel.com/coworking"]]], ["trececielos", "13 Cielos Hostel & Co-Work", "Francisco I. Madero 58; a hostel with a cowork room", "About US$6.50 a day or US$32 a week (2024 prices). 8am–10pm."], ["brucken", "Brücken", "the fastest wifi, up to 260 Mbps; open 24 hours", "About US$5 a day or US$50 a month (2024 prices). A 1.5 km walk from the centre."]]], ["CAFÉS WITH WIFI", [["aguacate", "Aguacate Veggie Bar", "fast wifi, indoor tables; weekend brunch 180 pesos"], ["casajasmine", "Casa Jasmine", "Indonesian restaurant and co-living; menú del día 140 pesos"], ["frontera", "Frontera & La Espirituosa", "two cafés sharing a leafy courtyard; fast wifi, long menu"], ["sarajevo", "Sarajevo Café", "lots of tables; menú del día 150 pesos, lunch 1–6pm"], ["kukulpan", "Kukulpan", "bakery with brunch, fresh juice and outdoor seats"], ["astro", "Astro Café", "courtyard with comfortable seats"]]]], "note": "Coworking and cafés don’t count towards progress: tick them if you like."}, {"id": "food", "number": "07", "title": "Food & drinks", "timing": "WHENEVER WE’RE HUNGRY", "color": "pink", "description": "Everything saved on my map, plus the local spirit.", "sections": [["EAT", [["comal", "Comal, Cocina de Barro", "cooking in clay pots"], ["achiote", "Achiote Cochinita Pibil", "cochinita pibil tacos and tortas"], ["catanzaro", "Trattoria Catanzaro", "Italian"], ["bangcook", "Bangcook Tailandés", "Thai"], ["casadeahn", "Casa de Ahn", "saved on my map"]]], ["COFFEE, BREAD & CHOCOLATE", [["xut", "XUT Café de Chiapas", "Chiapas coffee"], ["roots", "Panadería Artesanal Roots", "artisan bakery"], ["jangala", "Jangala", "chocolatería: cacao, ice cream and a chocolate workshop"]]], ["DRINK", [["pox", "A pox tasting", "the Chiapas spirit of corn and sugar cane, pronounced “posh”"]]]], "note": "Food and drinks don’t count towards progress."}, {"id": "sumidero", "number": "SAT", "title": "Cañón del Sumidero & Chiapa de Corzo", "timing": "OUR FIRST SATURDAY · A FULL DAY", "color": "blue", "weekend": true, "description": "A boat between canyon walls up to a kilometre high, the viewpoints from above, then the old river town. It’s about 1,700 m lower than San Cristóbal, so it’s hot.", "table": {"caption": "How to do the canyon", "map": "Map", "days": [["Tours · saved on GetYourGuide", [["8–9 hours", "★ Canyon, Viewpoints & Chiapa de Corzo", "Boat, the viewpoints and the town. From €68 each; rated 4.6.", "Leaves from San Cristóbal", "Cañón del Sumidero embarcadero Chiapa de Corzo", "https://www.getyourguide.com/san-cristobal-de-las-casas-l2166/san-cristobal-canyon-viewpoints-chiapa-de-corzo-tour-t112135/"], ["8 hours", "Sumidero Canyon & Chiapa de Corzo Boat Tour", "The pricier one, with hotel pickup. From €141 each; rated 4.6.", "Pickup in San Cristóbal", "Chiapa de Corzo Chiapas", "https://www.getyourguide.com/san-cristobal-de-las-casas-l2166/san-cristobal-sumidero-canyon-and-chiapa-de-corzo-tour-t593840/"]]], ["On our own", [["All day", "Bus, then colectivo to Chiapa de Corzo", "Shared boats leave from the embarcadero when full; about 230–280 pesos each. No viewpoints this way.", "About 1.5 hours each way", "Embarcadero Chiapa de Corzo"]]]]}, "sections": [["THE CANYON", [["canyonboat", "Boat through the canyon", "about two hours on the Grijalva: crocodiles, spider monkeys, the Christmas Tree waterfall"], ["miradores", "The canyon viewpoints", "looking straight down from the rim"]]], ["CHIAPA DE CORZO", [["lapila", "La Pila", "the 16th-century brick fountain on the main square"], ["chiapawander", "A wander and lunch by the river", "try pozol, the cold cacao and corn drink"]]]], "note": "Hat, sunscreen and a layer for the boat: it’s fast and windy on the water, then hot in town."}, {"id": "chamula", "number": "SAT", "title": "San Juan Chamula & Zinacantán", "timing": "OUR SECOND SATURDAY · MORNING OUT, FREE AFTERNOON", "color": "pink", "weekend": true, "description": "Two Tzotzil Maya villages ten kilometres from town. One church like nowhere else, and a weaving family’s house.", "table": {"caption": "How to get to the villages", "map": "Map", "days": [["Tour · saved on GetYourGuide", [["5 hours", "★ Chamula and Zinacantán Guided Tour", "Both villages with a guide, which helps: the church makes little sense without one. From €19 each; rated 4.5.", "Leaves from San Cristóbal", "San Juan Chamula Chiapas", "https://www.getyourguide.com/san-cristobal-de-las-casas-l2166/from-san-cristobal-chamula-and-zinacantan-guided-tour-t112333/"]]], ["Colectivo · our own pace", [["20 minutes", "Colectivo from the market", "About 25 pesos each per ride. A second colectivo links the two villages.", "10 km north-west", "San Juan Chamula Chiapas"]]]]}, "sections": [["SAN JUAN CHAMULA", [["chamulachurch", "Iglesia de San Juan Bautista", "pine needles on the floor, hundreds of candles, no pews", "About 25 pesos to enter. No photos inside, ever: phones stay in pockets."], ["chamulasquare", "The square and its market", "wool, fruit and men in white or black wool tunics"]]], ["ZINACANTÁN", [["zinacantan", "A weaving family’s house", "backstrap looms, embroidered flowers and tortillas off the comal"], ["sanlorenzo", "Iglesia de San Lorenzo", "the white church, full of fresh flowers"]]]], "note": "Sunday is Chamula’s big market day, so Saturday is calmer. Back by early afternoon, with the rest of the day free."}];

const optional = [["palenque", "Palenque, Agua Azul & Misol-Há", "a very long day: 14–19 hours, leaving around 4am", "A maybe. The tour saved on GetYourGuide is from €78 each. Blockades can close the road at short notice, so check the day before. An overnight in Palenque would be kinder.", [["GetYourGuide · Palenque day tour", "https://www.getyourguide.com/san-cristobal-de-las-casas-l2166/san-cris-agua-azul-misol-ha-z-arq-palenq-spanish-t457578/"]]]];
const KEY='frolicking-nicky-san-cristobal-v1';
let checked={}; let storageOK=true;
try { const saved=JSON.parse(localStorage.getItem(KEY)||'{}'); if(saved && typeof saved==='object' && !Array.isArray(saved)) checked=saved; } catch {storageOK=false;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const OPTIONAL_IDS=new Set(["centralita", "jovel", "trececielos", "brucken", "aguacate", "casajasmine", "frontera", "sarajevo", "kukulpan", "astro", "comal", "achiote", "catanzaro", "bangcook", "casadeahn", "xut", "roots", "jangala", "pox"]);
const countedIds=()=>groups.filter(()=>true).flatMap(g=>g.sections.flatMap(s=>s[1].map(r=>r[0]))).filter(id=>!OPTIONAL_IDS.has(id));
function item(row,extra=false) {const [id,title,desc,note,links]=row;return `<label class="task${checked[id]===true?' completed':''}"><input type="checkbox" id="${esc(id)}" data-extra="${extra}" ${checked[id]===true?'checked':''}><span class="checkmark" aria-hidden="true"></span><span class="task-copy"><span class="task-title">${esc(title)}</span> <span class="specialty">(${esc(desc)})</span>${note?`<span class="task-note">${esc(note)}</span>`:''}${links&&links.length?`<span class="fn-task-links">${links.map(([l,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(l)} ↗︎</a>`).join('')}</span>`:''}</span></label>`;}
const PHOTOS={"centro": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Catedral_de_San_Crist%C3%B3bal_de_las_Casas_1.jpg/1280px-Catedral_de_San_Crist%C3%B3bal_de_las_Casas_1.jpg", "The yellow and red baroque front of San Cristóbal’s cathedral", 1280, 997, "GameOfLight", "CC BY-SA 3.0", "https://commons.wikimedia.org/wiki/File:Catedral_de_San_Crist%C3%B3bal_de_las_Casas_1.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/1/13/San_Cristobal_de_las_Casas%2C_Iglesia_de_Nuestra_Se%C3%B1ora_de_Guadalupe.jpg/1280px-San_Cristobal_de_las_Casas%2C_Iglesia_de_Nuestra_Se%C3%B1ora_de_Guadalupe.jpg", "The white and gold Iglesia de Guadalupe at the top of its steps", 1280, 853, "Anthony G. Reyes", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:San_Cristobal_de_las_Casas,_Iglesia_de_Nuestra_Se%C3%B1ora_de_Guadalupe.jpg"]]], "markets": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/d/da/San_Crist%C3%B3bal_de_Las_Casas%2C_Chiapas%2C_Mexico%2C_2022_-_15.jpg/1280px-San_Crist%C3%B3bal_de_Las_Casas%2C_Chiapas%2C_Mexico%2C_2022_-_15.jpg", "A fruit stall under bright umbrellas at the market in San Cristóbal", 1280, 976, "Globetrotteur17", "CC BY-SA 2.0", "https://commons.wikimedia.org/wiki/File:San_Crist%C3%B3bal_de_Las_Casas,_Chiapas,_Mexico,_2022_-_15.jpg"]]], "sumidero": [[["https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Sumidero_Canyon%2C_Chiapas.jpg/1280px-Sumidero_Canyon%2C_Chiapas.jpg", "The green river between the high walls of the Sumidero Canyon", 1280, 590, "Sgroey", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Sumidero_Canyon,_Chiapas.jpg"]], [["https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Ca%C3%B1on_del_Sumidero%2C_Chiapas%2C_M%C3%A9xico.jpg/1280px-Ca%C3%B1on_del_Sumidero%2C_Chiapas%2C_M%C3%A9xico.jpg", "Looking along the water into the Sumidero Canyon", 1280, 960, "Christopher Javier Cuenca García", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Ca%C3%B1on_del_Sumidero,_Chiapas,_M%C3%A9xico.jpg"]]]};
const fig=([src,alt,w,h,by,lic,url])=>`<figure class="fn-v-photo"><a href="${src}" target="_blank" rel="noopener"><img src="${src}" alt="${esc(alt)}" width="${w}" height="${h}" loading="lazy"></a></figure>`;
const muertosTable=(t,gid)=>{const pick=0;return `<div class="fn-plan-tabs" role="tablist" aria-label="${esc(t.caption)}">${t.days.map(([day],i)=>`<button type="button" role="tab" id="fn-plan-tab-${gid}-${i}" aria-controls="fn-plan-day-${gid}-${i}" aria-selected="${i===pick}" tabindex="${i===pick?0:-1}">${esc(day.split(' · ')[0])}</button>`).join('')}</div>${t.days.map(([day,rows],i)=>`<div class="fn-plan-panel" role="tabpanel" id="fn-plan-day-${gid}-${i}" aria-labelledby="fn-plan-tab-${gid}-${i}"${i===pick?'':' hidden'}>${day.includes(' · ')?`<p class="fn-plan-sub">${esc(day.split(' · ').slice(1).join(' · '))}</p>`:''}<ol class="fn-plan-stops">${rows.map(([when,plan,what,where,q,url])=>`<li${/★/.test(plan)?' class="fn-plan-star"':''}><span class="fn-plan-when">${esc(when)}</span><div><p class="fn-plan-name">${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(plan)} ↗︎</a>`:esc(plan)}</p><p class="fn-plan-what">${esc(what)}</p><p class="fn-plan-where">${esc(where)} <a class="fn-plan-map" href="https://www.google.com/maps/search/?api=1&amp;query=${encodeURIComponent(q)}" target="_blank" rel="noopener noreferrer">${esc(t.map)}</a></p></div></li>`).join('')}</ol></div>`).join('')}`;};
let rowN=0;
document.querySelector('#itinerary').innerHTML=groups.map(g=>`<section id="${g.id}" class="outing fn-split ${g.color} ${g.weekend?'weekend':''}" aria-labelledby="title-${g.id}"><div class="outing-heading"><span class="number" aria-hidden="true">${g.number}</span><div><p class="eyebrow">${g.timing}</p><h2 id="title-${g.id}">${g.title}</h2><p class="section-desc">${g.description}</p></div><span class="group-count" id="count-${g.id}" aria-label="Section completion"></span></div>${g.table?`<div class="fn-plan-wrap">${muertosTable(g.table,g.id)}</div>`:''}<div class="outing-body fn-split-body"${g.sections.length?'':' hidden'}>${g.sections.map(([title,rows],si)=>{const ps=(PHOTOS[g.id]||[])[si]||[];const card=`<div class="task-group"><h3>${title}</h3>${rows.map(r=>item(r,OPTIONAL_IDS.has(r[0]))).join('')}</div>`;return ps.length?`<div class="fn-v-row${rowN++%2?' fn-v-rev':''}"><div class="fn-v-side">${ps.map(fig).join('')}</div>${card}</div>`:card;}).join('')}</div><div class="outing-note"><p>${g.note}</p>${g.link?`<a href="${g.link[1]}" target="_blank" rel="noopener noreferrer">${g.link[0]} ↗︎</a>`:''}</div></section>`).join('');
document.querySelectorAll('.fn-plan-tabs').forEach(list=>{const tabs=[...list.querySelectorAll('[role=tab]')];const show=(tab,focus)=>{tabs.forEach(b=>{const on=b===tab;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;document.getElementById(b.getAttribute('aria-controls')).hidden=!on;});if(focus)tab.focus();};tabs.forEach((b,i)=>{b.addEventListener('click',()=>show(b));b.addEventListener('keydown',e=>{const n={ArrowRight:i+1,ArrowLeft:i-1,Home:0,End:tabs.length-1}[e.key];if(n===undefined)return;e.preventDefault();show(tabs[(n+tabs.length)%tabs.length],true);});});});
document.querySelector('#optional-list').innerHTML=optional.map(r=>item(r,true)).join('');
function update(announce=false){const mainIds=countedIds();const done=mainIds.filter(id=>checked[id]===true).length;const percent=Math.round(done/mainIds.length*100);document.querySelector('#progress-count').textContent=done;document.querySelector('#progress-total').textContent=`of ${mainIds.length} places & moments`;document.querySelector('#percent').textContent=percent+'%';document.querySelector('#progress').value=percent;document.querySelector('#progress').textContent=percent+'%';groups.forEach(g=>{const inactive=false;const ids=g.sections.flatMap(s=>s[1].map(r=>r[0])).filter(id=>!OPTIONAL_IDS.has(id));document.querySelector('#count-'+g.id).hidden=!ids.length;document.querySelector('#count-'+g.id).textContent=inactive?"Alternative: excluded from checklist":`${ids.filter(id=>checked[id]===true).length} / ${ids.length}`;});const extra=[...optional.map(r=>r[0]),...OPTIONAL_IDS].filter(id=>checked[id]===true).length;document.querySelector('#extra-count').textContent=`${extra} optional ${extra===1?'stop':'stops'} done`;document.querySelector('#save-note').textContent=storageOK?'Progress saved on this device.':'Progress works here, but saving is unavailable in this browser.';if(announce)document.querySelector('#announcement').textContent=`${done} of ${mainIds.length} main items complete. ${extra} optional stops done.`;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(checked));storageOK=true;}catch{storageOK=false;}}
document.addEventListener('change',e=>{if(!e.target.matches('.task input'))return;checked[e.target.id]=e.target.checked;e.target.closest('.task').classList.toggle('completed',e.target.checked);persist();update(true);});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{const next=JSON.parse(e.newValue||'{}');checked=next&&typeof next==='object'&&!Array.isArray(next)?next:{};}catch{checked={};}document.querySelectorAll('.task input').forEach(el=>{el.checked=checked[el.id]===true;el.closest('.task').classList.toggle('completed',el.checked);});update();});
const dialog=document.querySelector('#reset-dialog');document.querySelector('#reset').addEventListener('click',()=>dialog.showModal());document.querySelector('#cancel-reset').addEventListener('click',()=>dialog.close());document.querySelector('#confirm-reset').addEventListener('click',()=>{checked={};persist();document.querySelectorAll('.task input').forEach(el=>{el.checked=false;el.closest('.task').classList.remove('completed');});update(true);dialog.close();});
update();
